ROOT=Path(__file__).resolve().parents[2];HERE=Path(__file__).parent
def load(s):return json.loads((HERE/f'numbered_051_101_{s}.json').read_text(encoding='utf-8'))
reads=load('reads');capsules={r['pilot']:r for r in load('capsules')};census={r['pilot']:r for r in load('census')};dups={r['pilot']:r for r in load('duplicates')};probe=load('probe')
def sha(p):return hashlib.sha256((ROOT/p).read_bytes()).hexdigest()
def ev(p,level='selected_public_source_review',bounds=None):
    return {'path':p,'lines':bounds or [1,len((ROOT/p).read_text(encoding='utf-8').splitlines())],'sha256':sha(p),'review_level':level}
def reviewed(prefix):return [r for r in reads if r['path'].startswith(prefix)]
