families={n['id']:n for n in registry['nodes'] if n.get('kind')=='existing_workflow_family'}
registry_text=(ROOT/'dag/workflows_dag.json').read_text(encoding='utf-8').splitlines()
def family(f,relation):
    n=families[f];start=next(i+1 for i,l in enumerate(registry_text) if re.search(r'"id": "'+f+r'"',l));end=start
    while end<len(registry_text) and not re.search(r'"id": ',registry_text[end]):end+=1
    return {'family_id':f,'path':n['path'],'relationship':relation,'registry_source_evidence':ev('dag/workflows_dag.json','family_identity_process_and_math_compared_not_composition_nodes',[start,end])}

